<script setup lang="ts">
import { onMounted, ref } from "vue";
import { Check, Play, RefreshCw, Scale, X } from "@lucide/vue";
import type { ScoreStabilityComparison, ScoreStabilityDecision, ScoreStabilityRunView } from "@/api/scoreStabilityExperiment";
import { compareScoreStability, decideScoreStability, getScoreStabilityRuns, resumeScoreStability, startScoreStability } from "@/api/scoreStabilityExperiment";
const runs=ref<ScoreStabilityRunView[]>([]), name=ref("评分稳定性基线"), baseline=ref(""), candidate=ref(""), comparison=ref<ScoreStabilityComparison|null>(null), busy=ref(false), error=ref("");
async function refresh(){busy.value=true;try{runs.value=await getScoreStabilityRuns();}catch(e:any){error.value=e?.response?.data?.message??"读取评分稳定性实验失败";}finally{busy.value=false;}}
async function start(){busy.value=true;try{await startScoreStability(name.value);await refresh();}catch(e:any){error.value=e?.response?.data?.message??"启动评分稳定性实验失败";}finally{busy.value=false;}}
async function resume(id:string){busy.value=true;try{await resumeScoreStability(id);await refresh();}catch(e:any){error.value=e?.response?.data?.message??"恢复评分稳定性实验失败";}finally{busy.value=false;}}
async function compare(){if(!baseline.value||!candidate.value)return;try{comparison.value=await compareScoreStability(baseline.value,candidate.value);}catch(e:any){error.value=e?.response?.data?.message??"比较评分稳定性实验失败";}}
async function decide(decision:ScoreStabilityDecision){if(!baseline.value||!candidate.value)return;try{await decideScoreStability(candidate.value,baseline.value,decision,decision==="ADOPTED"?"评分稳定性和知识依据护栏满足采用门槛":"评分波动或知识依据护栏未通过");await refresh();}catch(e:any){error.value=e?.response?.data?.message??"保存评分稳定性结论失败";}}
function formatDelta(code:string, delta:number){if(code==="latencyP95Ms"||code==="averageScoreRange"||code==="averageScore")return `${delta>=0?"+":""}${delta.toFixed(1)}`;return `${delta>=0?"+":""}${(delta*100).toFixed(1)}%`;}
onMounted(refresh);
</script>
<template>
 <section class="stability-panel">
  <header><div><span>Stage 11.1</span><h2>评分稳定性实验</h2><p>固定 5 题，每个可评分样本重复 2 次；中断后只补缺失重复，比较分数波动与知识依据判断。</p></div><button class="icon-button" title="刷新" @click="refresh"><RefreshCw :size="16"/></button></header>
  <div class="start-row"><input v-model="name" maxlength="100" aria-label="评分稳定性实验名称"><button @click="start" :disabled="busy"><Play :size="15"/>启动实验</button></div>
  <p v-if="error" class="error-banner" role="alert">{{ error }}</p>
  <div class="runs" aria-live="polite"><article v-for="item in runs" :key="item.run.runId" :class="{selected:item.run.runId===baseline||item.run.runId===candidate}"><div><strong>{{ item.run.name }}</strong><small>{{ item.run.status }} · {{ item.succeededCaseCount }}/{{ item.run.totalCaseCount }} · 重复 {{ item.run.repeatCount }} 次 · {{ item.run.modelName }}</small></div><div class="actions"><button title="设为基线" @click="baseline=item.run.runId"><Scale :size="14"/>基线</button><button title="设为候选" @click="candidate=item.run.runId"><Check :size="14"/>候选</button><button v-if="item.run.status!=='SUCCEEDED'" title="恢复" @click="resume(item.run.runId)"><RefreshCw :size="14"/></button></div><dl v-if="item.run.report"><div><dt>稳定样本</dt><dd>{{ (item.run.report.stableCaseRate*100).toFixed(1) }}%</dd></div><div><dt>平均波动</dt><dd>{{ item.run.report.averageScoreRange.toFixed(1) }}</dd></div><div><dt>平均分</dt><dd>{{ item.run.report.averageScore.toFixed(1) }}</dd></div></dl></article></div>
  <div v-if="baseline&&candidate" class="compare"><button @click="compare"><Scale :size="15"/>比较选中运行</button><div v-if="comparison" class="metrics"><div v-for="metric in comparison.metrics" :key="metric.code"><span>{{ metric.label }}</span><strong :class="{bad:(metric.higherIsBetter&&metric.delta<0)||(!metric.higherIsBetter&&metric.delta>0)}">{{ formatDelta(metric.code,metric.delta) }}</strong></div></div><p v-if="comparison" :class="comparison.safeguardsPassed?'pass':'fail'">{{ comparison.safeguardsPassed?'通过评分稳定性与知识依据护栏':'未通过评分稳定性与知识依据护栏：'+comparison.safeguardFailures.join('、') }}</p><div v-if="comparison" class="decision-actions"><button @click="decide('ADOPTED')"><Check :size="14"/>采用候选</button><button @click="decide('REJECTED')"><X :size="14"/>回退候选</button></div></div>
 </section>
</template>
<style scoped>
.stability-panel{display:grid;gap:var(--space-lg);padding-top:var(--space-xl);border-top:var(--rule-thin) solid var(--color-ink)} header{display:flex;justify-content:space-between;gap:var(--space-md)} header span{color:var(--color-muted);font-size:var(--text-xs)} h2{margin:var(--space-2xs) 0 0;font-family:var(--font-display);font-size:var(--text-xl)} header p{margin:var(--space-xs) 0 0;color:var(--color-muted)} button{display:inline-flex;align-items:center;gap:var(--space-2xs);border:var(--rule-thin) solid var(--color-ink);background:var(--color-paper);padding:var(--space-xs) var(--space-sm);cursor:pointer}.icon-button{width:2.25rem;height:2.25rem;justify-content:center;padding:0}.start-row{display:flex;gap:var(--space-sm)} input{min-width:16rem;padding:var(--space-xs) var(--space-sm);border:var(--rule-thin) solid var(--color-ink);background:var(--color-paper)}.runs{display:grid;gap:var(--space-sm)}article{display:grid;gap:var(--space-sm);padding:var(--space-md);border:var(--rule-thin) solid var(--color-rule);background:var(--color-paper-2)}article.selected{border-color:var(--color-accent)}small{display:block;color:var(--color-muted);margin-top:var(--space-2xs)}.actions{display:flex;gap:var(--space-xs);flex-wrap:wrap}dl{display:flex;gap:var(--space-lg);margin:0;flex-wrap:wrap}dt{color:var(--color-muted);font-size:var(--text-xs)}dd{margin:0;font-weight:700}.compare{display:grid;gap:var(--space-md);padding:var(--space-md);background:var(--color-paper-2)}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--space-sm)}.metrics div{display:grid;gap:var(--space-2xs);padding:var(--space-sm);border:var(--rule-thin) solid var(--color-rule)}.metrics span{font-size:var(--text-xs);color:var(--color-muted)}.bad,.fail{color:var(--color-error)}.pass{color:var(--color-success)}.decision-actions{display:flex;gap:var(--space-sm)}.error-banner{margin:0;padding:var(--space-sm);color:var(--color-error);background:var(--color-error-soft)}@media(max-width:42rem){.start-row{flex-direction:column}.start-row input{min-width:0}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
